INSERT INTO `exercise_catalog` (`id`,`name`,`category`,`equipment`,`muscle_groups`,`contraindication_tags`,`technique`,`regression`,`progression`,`substitution_ids`,`catalog_version`,`created_at`,`updated_at`) VALUES
('chair-march','{"en":"Seated chair march","vi":"Nâng gối tại ghế"}','aerobic','["chair"]','["hips","legs","cardiovascular"]','["balance_risk","hip_pain"]','{"en":"Sit tall on a stable chair and slowly lift one knee at a time while breathing normally.","vi":"Ngồi thẳng trên ghế vững và từ từ nâng từng gối, thở bình thường."}','{"en":"Make the lift smaller or hold the chair sides.","vi":"Nâng thấp hơn hoặc giữ hai bên ghế."}','{"en":"Add a few controlled repetitions only at a scheduled check-in.","vi":"Chỉ thêm vài lần có kiểm soát tại lần đánh giá định kỳ."}','["treadmill-walk"]','starter-1',1788028698062,1788028698062),
('dumbbell-floor-press','{"en":"Dumbbell floor press","vi":"Đẩy tạ nằm sàn"}','strength','["dumbbells","exercise mat"]','["chest","arms"]','["shoulder_pain","wrist_pain"]','{"en":"Lie on a mat, keep wrists neutral, press light dumbbells smoothly, and stop before shoulder discomfort.","vi":"Nằm trên thảm, giữ cổ tay trung tính, đẩy tạ nhẹ êm và dừng trước khi khó chịu ở vai."}','{"en":"Use no weights and practise the motion, or choose a wall push-up.","vi":"Không dùng tạ để tập động tác, hoặc chọn chống đẩy tường."}','{"en":"Increase load only after pain-free technique and a scheduled review.","vi":"Chỉ tăng tải sau khi kỹ thuật không đau và đã được đánh giá định kỳ."}','["wall-push-up"]','starter-1',1788028698062,1788028698062),
('dumbbell-hip-hinge','{"en":"Dumbbell hip hinge","vi":"Gập hông với tạ"}','strength','["dumbbells"]','["glutes","legs","back"]','["back_pain","knee_pain"]','{"en":"Hold light weights close to your legs, hinge from the hips with a long spine, then stand tall without holding your breath.","vi":"Giữ tạ nhẹ sát chân, gập từ hông với lưng thẳng rồi đứng lên, không nín thở."}','{"en":"Practise without weights or use a smaller range.","vi":"Tập không tạ hoặc giảm biên độ."}','{"en":"Add a small amount of load only after comfortable recovery and review.","vi":"Chỉ tăng ít tải sau khi hồi phục thoải mái và được đánh giá."}','["sit-to-stand"]','starter-1',1788028698062,1788028698062),
('gym-cable-row','{"en":"Gym cable row","vi":"Kéo cáp tại phòng gym"}','strength','["gym","cable machine"]','["back","arms"]','["shoulder_pain"]','{"en":"Set a light load, keep a tall torso, pull elbows toward your sides, and return slowly.","vi":"Đặt tải nhẹ, giữ thân thẳng, kéo khuỷu tay về hai bên rồi trả chậm."}','{"en":"Use a lighter load or resistance-band row.","vi":"Dùng tải nhẹ hơn hoặc kéo dây kháng lực."}','{"en":"Increase repetitions before load, only at a scheduled check-in.","vi":"Tăng số lần trước khi tăng tải, chỉ tại lần đánh giá định kỳ."}','["band-row"]','starter-1',1788028698062,1788028698062);
